        l10n.settingsTitle,
        l10n.languageSetting,
        l10n.switchLanguageButton,
        l10n.systemLanguage,
      ];
      for (final message in messages) {
        expect(
          message,
          isNotEmpty,
          reason: '${locale.languageCode}: message must be translated',
        );
      }
    }
  });

  test('Russian and Spanish provide real translations', () {
